import re

_REF_RE = re.compile(r"\$\{([^}]*)\}")
_HEADER_RE = re.compile(r"^\[([^\[\]]*)\]$")


def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    cur: str | None = None
    continuation_key: tuple[str, str] | None = None

    for raw_line in text.splitlines():
        stripped = raw_line.strip()

        if not stripped:
            continue
        if stripped[0] == ";" or stripped[0] == "#":
            continue

        if stripped.startswith("["):
            m = _HEADER_RE.match(stripped)
            if not m:
                raise ValueError("malformed section header")
            name = m.group(1).strip()
            if not name:
                raise ValueError("malformed section header")
            cur = name
            sections.setdefault(cur, {})
            continuation_key = None
            continue

        if raw_line[0] in " \t" and continuation_key is not None:
            sec, key = continuation_key
            sections[sec][key] += "\n" + stripped
            continue

        if cur is None:
            raise ValueError("key line before any section header")

        i_eq = stripped.find("=")
        i_col = stripped.find(":")
        positions = [i for i in (i_eq, i_col) if i >= 0]
        if not positions:
            raise ValueError("malformed line")

        pos = min(positions)
        key = stripped[:pos].strip().lower()
        value_part = stripped[pos + 1:].strip()
        if not key:
            raise ValueError("malformed line")

        if value_part.startswith('"'):
            end = value_part.find('"', 1)
            if end == -1:
                raise ValueError("malformed line")
            value = value_part[1:end]
            rest = value_part[end + 1:].strip()
            if rest and rest[0] not in ";#":
                raise ValueError("malformed line")
        else:
            comment_idx = None
            for i in range(len(value_part) - 1):
                if value_part[i] in " \t" and value_part[i + 1] in ";#":
                    comment_idx = i
                    break
            if comment_idx is not None:
                value = value_part[:comment_idx].strip()
            else:
                value = value_part.strip()

        sections[cur][key] = value
        continuation_key = (cur, key)

    default_values = sections.get("DEFAULT", {})

    def get_raw(sec: str, key: str):
        merged = dict(default_values)
        merged.update(sections.get(sec, {}))
        return merged.get(key)

    def interpolate(value: str, section_name: str, stack: list) -> str:
        def replace(match):
            content = match.group(1).strip()
            if ":" in content:
                sec_part, _, key_part = content.partition(":")
                target_sec = sec_part.strip()
                key = key_part.strip().lower()
            else:
                target_sec = section_name
                key = content.lower()
            if not target_sec or not key:
                raise KeyError("invalid interpolation reference")
            if target_sec not in sections:
                raise KeyError(f"missing section: {target_sec}")
            raw = get_raw(target_sec, key)
            if raw is None:
                raise KeyError(f"missing key: {key}")
            if (target_sec, key) in stack:
                raise ValueError(f"cyclic reference: {target_sec}:{key}")
            return interpolate(raw, target_sec, stack + [(target_sec, key)])

        return _REF_RE.sub(replace, value)

    result: dict[str, dict[str, str]] = {}
    for sec_name, sec_values in sections.items():
        if sec_name == "DEFAULT":
            continue
        effective: dict[str, str] = {}
        effective.update(default_values)
        effective.update(sec_values)
        interpolated: dict[str, str] = {}
        for key, val in effective.items():
            interpolated[key] = interpolate(val, sec_name, [(sec_name, key)])
        result[sec_name] = interpolated

    return result
