import re

def parse_duration(s: str) -> int:
    if not s.strip():
        raise ValueError("duration string must not be empty")

    match = re.fullmatch(r"(?:(\d+)[hH]\s*)?(?:(\d+)[mM]\s*)?(?:(\d+)[sS]\s*)?", s)
    if match is None:
        raise ValueError("invalid duration format")

    hours, minutes, seconds = match.groups()
    if hours is None and minutes is None and seconds is None:
        raise ValueError("duration string must not be empty")

    return (int(hours) * 3600 if hours is not None else 0) + (int(minutes) * 60 if minutes is not None else 0) + (int(seconds) if seconds is not None else 0)
