import re
import unicodedata

def slugify(title: str, max_len: int = 50) -> str:
    ascii_title = unicodedata.normalize('NFKD', title).encode('ascii', 'ignore').decode('ascii')
    slug = ascii_title.lower()
    slug = re.sub(r'[^a-z0-9]+', '-', slug).strip('-')

    if len(slug) > max_len:
        words = slug.split('-')
        prefix: list[str] = []
        length = 0
        for word in words:
            candidate = len(word) if not prefix else length + 1 + len(word)
            if candidate <= max_len:
                prefix.append(word)
                length = candidate
            else:
                break
        if prefix:
            slug = '-'.join(prefix)
        else:
            slug = slug[:max_len]

    return slug.rstrip('-')
