def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""
    uniq = sorted(set(nums))
    parts = []
    i = 0
    n = len(uniq)
    while i < n:
        j = i
        while j + 1 < n and uniq[j + 1] == uniq[j] + 1:
            j += 1
        if j - i + 1 >= 3:
            parts.append(f"{uniq[i]}..{uniq[j]}")
        else:
            parts.extend(str(x) for x in uniq[i:j + 1])
        i = j + 1
    return ",".join(parts)
