import re
from decimal import Decimal, InvalidOperation

def _parse_amount(text):
    if not isinstance(text, str):
        return None
    s = text.strip()
    if not s:
        return None
    sign = Decimal("1")
    if s.startswith("-"):
        sign = Decimal("-1")
        s = s[1:].lstrip()
    elif s.startswith("+"):
        s = s[1:].lstrip()
    if not s:
        return None
    if s.startswith("$"):
        s = s[1:].lstrip()
    s = s.replace(",", "").strip()
    if not re.fullmatch(r"[0-9]+(\.[0-9]+)?|\.[0-9]+", s):
        return None
    try:
        return sign * Decimal(s)
    except InvalidOperation:
        return None

def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    totals: dict[str, Decimal] = {}
    display: dict[str, str] = {}

    for row in rows:
        if not isinstance(row, dict):
            continue
        raw_name = row.get("customer")
        if not isinstance(raw_name, str):
            continue
        name = raw_name.strip()
        if not name:
            continue
        amount = _parse_amount(row.get("amount"))
        if amount is None:
            continue
        key = name.lower()
        if key not in totals:
            totals[key] = Decimal("0.00")
            display[key] = name
        totals[key] += amount

    result = []
    for key, total in totals.items():
        rounded = total.quantize(Decimal("0.01"))
        result.append((display[key], float(rounded)))

    result.sort(key=lambda item: (-item[1], item[0].lower(), item[0]))
    return result[:max(n, 0)]
```
